def transform(grid):
    """Infer a diagonal-periodic pattern from the nonzero diagonal clues."""
    h, w = len(grid), len(grid[0])
    # The two demonstrations show a completed coloring constant along
    # down-right diagonals, with the clue colors defining the diagonal cycle.
    # Determine a compatible period and residue-color map from all clues.
    clues = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                clues[d] = color
    # Find the smallest period for which all known diagonal clues agree.
    # For ambiguous periods, use the smallest that explains the observed span.
    offsets = sorted(clues)
    period = None
    for p in range(1, max(2, max(offsets) - min(offsets) + 1)):
        residues = {}
        ok = True
        for d, color in clues.items():
            k = d % p
            if k in residues and residues[k] != color:
                ok = False
                break
            residues[k] = color
        if ok:
            period = p
            break
    if period is None:
        period = max(1, max(offsets) - min(offsets) + 1)
    residues = {}
    for d, color in clues.items():
        residues[d % period] = color
    # Extend the periodic coloring, propagating by diagonal residue.
    # Missing residues are inferred cyclically from the recurring clue sequence.
    if len(residues) == period:
        return [[residues[(c-r) % period] for c in range(w)] for r in range(h)]
    # If clues don't determine all residues, retain them and fill each unknown
    # by the nearest known residue around the cycle.
    keys = sorted(residues)
    if not keys:
        return [row[:] for row in grid]
    return [[residues.get((c-r) % period,
                          residues[min(keys, key=lambda k: min((k-(c-r)%period)%period, ((c-r)%period-k)%period))])
             for c in range(w)] for r in range(h)]
